/***
 * MARK: RunnerBoxesRow
 * @description Row container for the Now Playing runner boxes (plan B2):
 *   `role="list"` labelled "Live runners", one `role="listitem"` per box.
 *   Renders null unless there are 1-4 entries — 0 or 5+ falls back to the
 *   legacy single-task view in the parent, so this component never decides
 *   the fallback itself. The row scrolls horizontally inside the bar's
 *   bounded left container (`flex-1 min-w-0`) and each box is `shrink-0`,
 *   so boxes can never paint under the centre transport controls.
 * @example <RunnerBoxesRow entries={[{ runnerId: 'bravo', runnerLabel: 'Bravo', task: { id: 't1' }, taskTitleFirstLine: 'Ship it', stageName: 'Plan', statusWord: 'running' }]} onOpenTask={(task) => setSelectedTask(task)} />
 * @param {Object} props - Component props.
 * @param {Array<Object>} props.entries - Runner entries (1-4 render, anything else returns null).
 * @param {Function} [props.onOpenTask] - Forwarded to each RunnerBox.
 * @returns {React.ReactElement|null} The row, or null when out of the 1-4 window.
 ***/
export function RunnerBoxesRow({ entries, onOpenTask }) {
  if (!Array.isArray(entries) || entries.length === 0 || entries.length > RUNNER_BOX_MAX_COUNT) {
    return null;
  }
  return (
    <div
      role="list"
      aria-label="Live runners"
      data-testid="runner-boxes-row"
      className="flex min-w-0 items-center gap-2 overflow-x-auto"
    >
      {entries.map((entry) => (
        <div
          key={String(entry?.runnerId ?? 'unknown')}
          role="listitem"
          className="min-w-0 shrink-0"
        >
          <RunnerBox entry={entry} onOpenTask={onOpenTask} />
        </div>
      ))}
    </div>
  );
}

import React from 'react';

import {
  buildRunnerBoxAriaLabel,
  formatRunnerStatusDisplay,
  getRunnerBoxStyle,
  truncateRunnerText,
} from './runnerBoxUi';

/***
 * MARK: RunnerBox
 * @description Compact per-runner box for the Now Playing bar (plan q2/q3):
 *   runner name, task first line, stage line, and a health indicator that is
 *   never colour-only — the status word renders as text beside the dot
 *   (WCAG 1.4.1) while the dot itself is aria-hidden. Lines truncate in CSS
 *   with the full value on `title`; the tooltip text is capped so a
 *   paragraph-long goal cannot build an unusable tooltip. A box WITH a task
 *   is a button that opens the task inspector; a box WITHOUT a task is a
 *   greyed-out `idle` panel (display-only, plan q5). Three short lines fit
 *   the 72px bar; the status word shares the name line so no fourth line is
 *   needed.
 * @example <RunnerBox entry={{ runnerId: 'bravo', runnerLabel: 'Bravo', task: { id: 't1' }, taskTitleFirstLine: 'Ship it', stageName: 'Plan', statusWord: 'running' }} onOpenTask={(task) => setSelectedTask(task)} />
 * @param {Object} props - Component props.
 * @param {Object} props.entry - Runner entry ({ runnerId, runnerLabel, task, taskTitleFirstLine, stageName, statusWord }).
 * @param {Function} [props.onOpenTask] - Called with the task when a task-carrying box is activated.
 * @returns {React.ReactElement} The box (button when it has a task, panel when idle).
 ***/
export function RunnerBox({ entry, onOpenTask }) {
  const runnerId = entry?.runnerId ?? 'unknown';
  const runnerName =
    typeof entry?.runnerLabel === 'string' && entry.runnerLabel.trim() !== ''
      ? entry.runnerLabel
      : String(runnerId);
  const statusWord = entry?.statusWord || 'idle';
  const style = getRunnerBoxStyle(statusWord);
  const testId = `runner-box-${runnerId}`;
  const label = buildRunnerBoxAriaLabel({ ...entry, runnerLabel: runnerName });
  const taskTitle =
    typeof entry?.taskTitleFirstLine === 'string' && entry.taskTitleFirstLine !== ''
      ? entry.taskTitleFirstLine
      : 'Untitled Task';
  const stageLine = entry?.stageName ? `Stage: ${entry.stageName}` : '—';

  const frameClass =
    'flex min-w-[120px] max-w-[180px] flex-col justify-center gap-0.5 rounded border border-border-standard bg-surface-container px-2 py-1 text-left';

  // Idle variant (plan q5): greyed-out panel, no click target. role="group"
  // so the aria-label (runner + status) stays valid on a non-interactive
  // element; the word `idle` is visible text, never colour-only.
  if (!entry?.task) {
    return (
      <div
        role="group"
        aria-label={label}
        data-testid={testId}
        title={truncateRunnerText(runnerName)}
        className={`${frameClass} opacity-60`}
      >
        <span className="flex min-w-0 items-center gap-1">
          <span className={`h-2 w-2 shrink-0 rounded-full ${style.dotClass}`} aria-hidden="true" />
          <span className="truncate text-[11px] font-bold text-text-muted" title={truncateRunnerText(runnerName)}>
            {runnerName}
          </span>
        </span>
        <span className="truncate text-[11px] text-text-muted">idle</span>
      </div>
    );
  }

  return (
    <button
      type="button"
      onClick={() => onOpenTask?.(entry.task)}
      aria-label={label}
      data-testid={testId}
      className={`${frameClass} cursor-pointer hover:bg-surface-container-high focus:outline-none focus:ring-1 focus:ring-primary`}
    >
      <span className="flex min-w-0 items-center gap-1">
        <span className={`h-2 w-2 shrink-0 rounded-full ${style.dotClass}`} aria-hidden="true" />
        <span
          className="min-w-0 flex-1 truncate text-[11px] font-bold text-on-surface"
          title={truncateRunnerText(runnerName)}
        >
          {runnerName}
        </span>
        <span className={`shrink-0 text-[10px] font-semibold uppercase tracking-wide ${style.statusClass}`}>
          {formatRunnerStatusDisplay(statusWord)}
        </span>
      </span>
      <span
        className="truncate text-[11px] text-on-surface"
        title={truncateRunnerText(taskTitle)}
      >
        {taskTitle}
      </span>
      <span
        className="truncate text-[10px] text-text-muted"
        title={entry?.stageName ? truncateRunnerText(stageLine) : undefined}
      >
        {stageLine}
      </span>
    </button>
  );
}

import { formatTaskTitleFirstLine, isTaskCompleted } from '../tasks/taskFormatters';
import { isEngineOwner, resolveDisplayedStage } from '../tasks/runningTask';
import { resolveRunnerStatusWord } from './runnerBoxUi';

/***
 * MARK: readTaskRunnerId
 * @description Runner identity carried by a task payload, if any. Reads the
 *   explicit `runnerId` field first, then the legacy `runner` field (string
 *   id or `{ id }` object). Returns null when the task carries no runner
 *   association — the bar then treats it as ordinary queue data, never as a
 *   runner box (see selectRunnerEntries).
 * @example readTaskRunnerId({ runnerId: 'bravo' }) => 'bravo'
 * @example readTaskRunnerId({ status: 'in_stage' }) => null
 * @param {Object} [task] - Task payload.
 * @returns {string|null} Trimmed runner id, or null.
 ***/
const readTaskRunnerId = (task) => {
  const raw = task?.runnerId ?? task?.runner;
  if (typeof raw === 'string') {
    const id = raw.trim();
    return id !== '' ? id : null;
  }
  if (raw && typeof raw === 'object' && typeof raw.id === 'string' && raw.id.trim() !== '') {
    return raw.id.trim();
  }
  return null;
};

/***
 * MARK: readTaskRunnerLabel
 * @description Human-readable runner name for a task: explicit
 *   `runnerName`/`runnerLabel` first, then an object-shaped `runner.name`,
 *   else the runner id itself (never blank).
 * @example readTaskRunnerLabel({ runnerId: 'b1', runnerName: 'Bravo' }, 'b1') => 'Bravo'
 * @example readTaskRunnerLabel({ runnerId: 'b1' }, 'b1') => 'b1'
 * @param {Object} [task] - Task payload.
 * @param {string} fallbackId - Runner id used when no name is carried.
 * @returns {string} Display label.
 ***/
const readTaskRunnerLabel = (task, fallbackId) => {
  const candidates = [task?.runnerName, task?.runnerLabel, task?.runner?.name];
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate.trim() !== '') return candidate.trim();
  }
  return fallbackId;
};

/***
 * MARK: taskRecency
 * @description Sort key for "most recent task wins" inside a runner group:
 *   updatedAt, then enteredStageAt/createdAt, then stable id order — the
 *   same pipeline-independent recency the universal now-playing fallback
 *   uses, so boxes agree with the bar about what is current.
 * @example taskRecency({}) => 0
 * @param {Object} [task] - Task payload.
 * @returns {number} Millis epoch (0 when unparseable).
 ***/
const taskRecency = (task) =>
  Date.parse(task?.updatedAt || task?.enteredStageAt || task?.createdAt || 0) || 0;

/***
 * MARK: pickGroupTask
 * @description The single task a runner group names: the engine owner when
 *   it belongs to this runner, else the most recently updated open task,
 *   else the most recently updated task of any state. Never invents one.
 * @example pickGroupTask([{ id: 'a' }], {}) => { id: 'a' }
 * @param {Array<Object>} [groupTasks] - Tasks sharing one runner id.
 * @param {Object} [engineState] - Engine snapshot (status/activeTaskId).
 * @returns {Object|null} The named task, or null for an empty group.
 ***/
const pickGroupTask = (groupTasks, engineState) => {
  const list = Array.isArray(groupTasks) ? groupTasks : [];
  if (list.length === 0) return null;
  const owner = list.find((task) => isEngineOwner(task, engineState));
  if (owner) return owner;
  const byRecency = [...list].sort((a, b) => {
    const time = taskRecency(b) - taskRecency(a);
    if (time !== 0) return time;
    return String(a?.id ?? '').localeCompare(String(b?.id ?? ''));
  });
  return byRecency.find((task) => !isTaskCompleted(task)) || byRecency[0] || null;
};

/***
 * MARK: selectRunnerEntries
 * @description Derives Now Playing runner box entries from data already in
 *   context — no runner registry, no fetching. Tasks carrying an explicit
 *   `runnerId`/`runner` field group by runner (one entry per runner); tasks
 *   without runner association contribute NOTHING, so the bar degrades to
 *   the legacy single-task view instead of misrepresenting queued tasks as
 *   live runners. That deliberately narrows the plan's provisional
 *   workflowId/per-task fallback: on this single-task engine an open task is
 *   queued work, not a runner, and the per-task fallback would both break
 *   the pinned single-active contract and flip existing single-task-view
 *   tests into box mode. A future registry swaps this one file; the
 *   `runnerEntries` prop on NowPlayingBar already accepts its output shape.
 * @example selectRunnerEntries({ tasks: [{ id: 't1', runnerId: 'b', status: 'in_stage' }], stages: [], engineState: { status: 'idle' } }) => [{ runnerId: 'b', runnerLabel: 'b', taskId: 't1', task: { id: 't1', runnerId: 'b', status: 'in_stage' }, taskTitleFirstLine: 'Untitled Task', stageName: null, statusWord: 'queued' }]
 * @example selectRunnerEntries({ tasks: [{ id: 't1', status: 'in_stage' }], stages: [], engineState: {} }) => []
 * @param {Object} [args] - Named inputs mirroring the bar's context.
 * @param {Array<Object>} [args.tasks] - Live task list.
 * @param {Array<Object>} [args.stages] - Pipeline stages for stage-name resolution.
 * @param {Object} [args.engineState] - Engine snapshot (status/activeTaskId).
 * @param {boolean} [args.isAgentRunning=false] - Agent-loop liveness flag.
 * @returns {Array<Object>} Runner entries sorted by runnerId (possibly empty).
 ***/
export function selectRunnerEntries({ tasks, stages, engineState, isAgentRunning = false } = {}) {
  const list = Array.isArray(tasks) ? tasks : [];
  const stageList = Array.isArray(stages) ? stages : [];
  const groups = new Map();
  for (const task of list) {
    if (!task || typeof task !== 'object') continue;
    const runnerId = readTaskRunnerId(task);
    if (!runnerId) continue;
    if (!groups.has(runnerId)) {
      groups.set(runnerId, {
        runnerId,
        runnerLabel: readTaskRunnerLabel(task, runnerId),
        tasks: [],
      });
    }
    const group = groups.get(runnerId);
    // A later task in the group may carry a nicer name than the first.
    const label = readTaskRunnerLabel(task, runnerId);
    if (label !== runnerId && group.runnerLabel === runnerId) group.runnerLabel = label;
    group.tasks.push(task);
  }
  return [...groups.values()]
    .map((group) => {
      const task = pickGroupTask(group.tasks, engineState);
      return {
        runnerId: group.runnerId,
        runnerLabel: group.runnerLabel,
        taskId: task?.id ?? null,
        task: task ?? null,
        taskTitleFirstLine: task ? formatTaskTitleFirstLine(task) : null,
        stageName: task
          ? (resolveDisplayedStage(task, stageList, engineState)?.name ?? null)
          : null,
        statusWord: resolveRunnerStatusWord(task, engineState, isAgentRunning),
      };
    })
    .sort((a, b) => String(a.runnerId).localeCompare(String(b.runnerId)));
}

